const TOOL_NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export const PROMPT_HASH = createHash("sha1").update(SYSTEM_PROMPT + SELLING_RULES + JSON.stringify(TOOL_DEFS)).digest("hex").slice(0, 12);

